##### 1. SOLID Principles

Apply to all object-oriented code (C#, Java, TypeScript):

| Principle | Description | Implementation Guidance |
|-----------|-------------|------------------------|
| **Single Responsibility** | Class should have one reason to change | Each class focuses on single business concern or technical responsibility |
| **Open/Closed** | Open for extension, closed for modification | Use interfaces, abstract classes, and dependency injection for extensibility |
| **Liskov Substitution** | Subtypes must be substitutable for base types | Ensure derived classes honor base class contracts and invariants |
| **Interface Segregation** | Many specific interfaces better than one general | Create focused interfaces; clients shouldn't depend on unused methods |
| **Dependency Inversion** | Depend on abstractions, not concretions | Use dependency injection; high-level modules don't depend on low-level details |

**SOLID Example - C# Service Architecture:**

```csharp
// SOLID-compliant service design

// Interface Segregation - Focused interfaces
public interface IClaimRepository
{
    Task<Claim> GetByIdAsync(Guid claimId);
    Task<IEnumerable<Claim>> GetByPatientIdAsync(Guid patientId);
    Task SaveAsync(Claim claim);
}

public interface IClaimValidator
{
    ValidationResult Validate(Claim claim);
}

public interface IClaimNotificationService
{
    Task NotifyClaimStatusChangeAsync(Guid claimId, ClaimStatus newStatus);
}

// Single Responsibility - Each class has one job
public class ClaimRepository : IClaimRepository
{
    private readonly DbContext _context;

    public ClaimRepository(DbContext context) // Dependency Inversion
    {
        _context = context;
    }

    public async Task<Claim> GetByIdAsync(Guid claimId)
    {
        return await _context.Claims.FindAsync(claimId);
    }

    // Other repository methods...
}

// Open/Closed - Extensible validation through strategy pattern
public abstract class ClaimValidator : IClaimValidator
{
    public virtual ValidationResult Validate(Claim claim)
    {
        var result = new ValidationResult();
        ValidateRequired(claim, result);
        ValidateBusinessRules(claim, result);
        return result;
    }

    protected abstract void ValidateBusinessRules(Claim claim, ValidationResult result);
}

public class MedicaidClaimValidator : ClaimValidator
{
    protected override void ValidateBusinessRules(Claim claim, ValidationResult result)
    {
        // Medicaid-specific validation rules
        if (claim.ServiceDate < claim.Patient.MedicaidEligibilityStartDate)
            result.AddError("Service date before Medicaid eligibility");
    }
}

// Dependency Inversion - Service depends on abstractions
public class ClaimProcessingService
{
    private readonly IClaimRepository _claimRepository;
    private readonly IClaimValidator _validator;
    private readonly IClaimNotificationService _notificationService;

    public ClaimProcessingService(
        IClaimRepository claimRepository,
        IClaimValidator validator,
        IClaimNotificationService notificationService)
    {
        _claimRepository = claimRepository;
        _validator = validator;
        _notificationService = notificationService;
    }

    public async Task<ProcessingResult> ProcessClaimAsync(Guid claimId)
    {
        var claim = await _claimRepository.GetByIdAsync(claimId);
        var validationResult = _validator.Validate(claim);

        if (!validationResult.IsValid)
            return ProcessingResult.ValidationFailed(validationResult);

        claim.Status = ClaimStatus.Approved;
        await _claimRepository.SaveAsync(claim);
        await _notificationService.NotifyClaimStatusChangeAsync(claimId, ClaimStatus.Approved);

        return ProcessingResult.Success();
    }
}
```

