**DDD Example - Aggregate with Ubiquitous Language:**

```csharp
// Ubiquitous language from business domain
public class Claim : AggregateRoot
{
    public Guid ClaimId { get; private set; }
    public MemberId MemberId { get; private set; }
    public ProviderId ProviderId { get; private set; }
    public ServiceDate ServiceDate { get; private set; }
    public ClaimStatus Status { get; private set; }

    private readonly List<ClaimLine> _claimLines = new();
    public IReadOnlyCollection<ClaimLine> ClaimLines => _claimLines.AsReadOnly();

    // Business methods using domain language
    public void Submit()
    {
        if (Status != ClaimStatus.Draft)
            throw new InvalidOperationException("Only draft claims can be submitted");

        if (!_claimLines.Any())
            throw new InvalidOperationException("Claim must have at least one service line");

        Status = ClaimStatus.Submitted;
        AddDomainEvent(new ClaimSubmittedEvent(ClaimId, MemberId, ServiceDate));
    }

    public void Adjudicate(AdjudicationResult result)
    {
        if (Status != ClaimStatus.Submitted)
            throw new InvalidOperationException("Only submitted claims can be adjudicated");

        Status = result.IsApproved ? ClaimStatus.Approved : ClaimStatus.Denied;

        if (result.IsApproved)
            AddDomainEvent(new ClaimApprovedEvent(ClaimId, result.ApprovedAmount));
        else
            AddDomainEvent(new ClaimDeniedEvent(ClaimId, result.DenialReason));
    }

    public void AddServiceLine(DiagnosisCode diagnosis, ProcedureCode procedure, Money chargeAmount)
    {
        if (Status != ClaimStatus.Draft)
            throw new InvalidOperationException("Cannot modify submitted claim");

        var claimLine = new ClaimLine(Guid.NewGuid(), diagnosis, procedure, chargeAmount);
        _claimLines.Add(claimLine);
    }
}
